-- Challenge 
-- Joining on multiple tables
-- Write SQL queries to perform the following tasks using the Sakila database:
USE Sakila;
-- List the number of films per category.

select category_id,count(film_id) as no_of_films 
from film_category
group by category_id;

-- Retrieve the store ID, city, and country for each store.

Select s.store_id,c.city,co.country from 
store as s join address as a
on s.address_id = a.address_id
join
city as c
on a.city_id = c.city_id
join
country as co
on c.country_id = co.country_id;

-- Calculate the total revenue generated by each store in dollars.

select st.store_id as store, sum(p.amount) as total_revenue 
from payment as p join staff as s
on p.staff_id = s.staff_id
join
store as st
on s.store_id = st.store_id
group by store;


-- Determine the average running time of films for each category.

select fc.category_id as film_category, round(avg(f.length),2) as avg_running_time
from film as f join film_category as fc
on f.film_id = fc.film_id
group by film_category;

-- Bonus:
-- Identify the film categories with the longest average running time.

select c.name as film_category, round(avg(f.length),2) as avg_running_time
from film as f join film_category as fc
on f.film_id = fc.film_id
join category as c
on 
fc.category_id = c.category_id
group by film_category
order by avg_running_time desc
limit 5;

-- Display the top 10 most frequently rented movies in descending order.
select f.title as film_title, count(rental_id) as rented_freq
from rental as r join inventory as i
on r.inventory_id = i.inventory_id
join
film as f
on i.film_id = f.film_id
group by film_title
order by rented_freq desc
limit 10 ;

-- Determine if "Academy Dinosaur" can be rented from Store 1.
SELECT f.title,count(*)
FROM inventory AS i JOIN film AS f
ON i.film_id = f.film_id
where f.title = "Academy Dinosaur" 
and store_id = 1;

-- Provide a list of all distinct film titles, along with their availability status in the inventory. Include a column indicating whether each title is 'Available' or 'NOT available.
select DISTINCT f.title,
CASE 
	WHEN i.film_id  IS NOT NULL THEN 'Available'
    ELSE 'NOT available'
    END AS availability_status
from film as f LEFT JOIN inventory as i
on f.film_id = i.film_id;

-- ' Note that there are 42 titles that are not in the inventory, and this information can be obtained using a CASE statement combined with IFNULL."

select
CASE 
	WHEN i.film_id  IS NULL THEN 'Not Available'
    ELSE 'available'
    END AS availability_status,
count(DISTINCT f.film_id) as num_titles
from film as f LEFT JOIN inventory as i
on f.film_id = i.film_id
GROUP BY availability_status;







